package com.global.ct.frameinventory.frame;

import org.springframework.http.HttpStatus;

final class FrameProblem extends RuntimeException {
    private final HttpStatus status;
    private final String code;
    private final Long currentVersionId;

    private FrameProblem(HttpStatus status, String code, String message, Long currentVersionId) {
        super(message);
        this.status = status;
        this.code = code;
        this.currentVersionId = currentVersionId;
    }

    static FrameProblem missing() {
        return new FrameProblem(HttpStatus.NOT_FOUND, "FRAME_NOT_FOUND", "The frame was not found.", null);
    }

    static FrameProblem reserved() {
        return new FrameProblem(HttpStatus.CONFLICT, "FRAME_ID_RESERVED", "This frame ID has already been used.", null);
    }

    static FrameProblem stale(Long currentVersionId) {
        String detail = currentVersionId == null
            ? "The frame no longer has a current version."
            : "The frame has changed. Fetch its current version before retrying.";
        return new FrameProblem(HttpStatus.CONFLICT, "STALE_FRAME_VERSION", detail, currentVersionId);
    }

    HttpStatus status() {
        return status;
    }

    String code() {
        return code;
    }

    Long currentVersionId() {
        return currentVersionId;
    }
}
EOF
