package com.global.ct.frameinventory.frame;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

import com.fasterxml.jackson.databind.JsonMappingException;

import org.springframework.beans.TypeMismatchException;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.HttpStatusCode;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.validation.Errors;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.context.request.WebRequest;
import org.springframework.web.method.annotation.HandlerMethodValidationException;
import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException;
import org.springframework.web.servlet.mvc.method.annotation.ResponseEntityExceptionHandler;

@RestControllerAdvice
class FrameExceptionHandler extends ResponseEntityExceptionHandler {
    @ExceptionHandler(FrameProblem.class)
    ProblemDetail handleFrameProblem(FrameProblem exception) {
        var problem = ProblemDetail.forStatusAndDetail(exception.status(), exception.getMessage());
        problem.setProperty("code", exception.code());
        if (exception.currentVersionId() != null) {
            problem.setProperty("currentVersionId", exception.currentVersionId());
        }
        return problem;
    }

    @Override
    protected ResponseEntity<Object> handleMethodArgumentNotValid(
        MethodArgumentNotValidException exception, HttpHeaders headers, HttpStatusCode status, WebRequest request
    ) {
        return invalid(exception, headers, request, fieldErrors(exception.getBindingResult()));
    }

    @Override
    protected ResponseEntity<Object> handleHandlerMethodValidationException(
        HandlerMethodValidationException exception, HttpHeaders headers, HttpStatusCode status, WebRequest request
    ) {
        if (exception.isForReturnValue()) {
            return super.handleHandlerMethodValidationException(exception, headers, status, request);
        }
        List<FieldProblem> errors = new ArrayList<>();
        for (var result : exception.getParameterValidationResults()) {
            if (result instanceof Errors binding) {
                errors.addAll(fieldErrors(binding));
            } else {
                String field = result.getMethodParameter().getParameterName();
                for (var error : result.getResolvableErrors()) {
                    errors.add(new FieldProblem(Objects.requireNonNullElse(field, "request"), error.getDefaultMessage()));
                }
            }
        }
        return invalid(exception, headers, request, errors);
    }

    @Override
    protected ResponseEntity<Object> handleTypeMismatch(
        TypeMismatchException exception, HttpHeaders headers, HttpStatusCode status, WebRequest request
    ) {
        String field = exception instanceof MethodArgumentTypeMismatchException mismatch ? mismatch.getName() : "request";
        return invalid(exception, headers, request, List.of(new FieldProblem(field, "Invalid value.")));
    }

    @Override
    protected ResponseEntity<Object> handleHttpMessageNotReadable(
        HttpMessageNotReadableException exception, HttpHeaders headers, HttpStatusCode status, WebRequest request
    ) {
        String field = "body";
        if (exception.getCause() instanceof JsonMappingException mapping && !mapping.getPath().isEmpty()) {
            var names = mapping.getPath().stream().map(JsonMappingException.Reference::getFieldName).toList();
            if (names.stream().allMatch(Objects::nonNull)) {
                field = String.join(".", names);
            }
        }
        return invalid(exception, headers, request, List.of(new FieldProblem(field, "Malformed or invalid JSON.")));
    }

    private ResponseEntity<Object> invalid(
        Exception exception, HttpHeaders headers, WebRequest request, List<FieldProblem> errors
    ) {
        var problem = ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST, "One or more request values are invalid.");
        problem.setProperty("code", "INVALID_REQUEST");
        problem.setProperty("errors", errors);
        return handleExceptionInternal(exception, problem, headers, HttpStatus.BAD_REQUEST, request);
    }

    private static List<FieldProblem> fieldErrors(Errors errors) {
        var fields = new ArrayList<FieldProblem>();
        errors.getFieldErrors().forEach(error -> fields.add(new FieldProblem(error.getField(), error.getDefaultMessage())));
        errors.getGlobalErrors().forEach(error -> fields.add(new FieldProblem("body", error.getDefaultMessage())));
        return fields;
    }

    record FieldProblem(String field, String message) {}
}
